# The networks' recorded errors, for the oracle to replay
# (TrajectorySensitivity.ReplayDraws): the car's (small_weak) and the cloud's
# (large) errors and own σ for every estimate, on every scan of the racer's
# own laps of the held-out tracks (driving on the true estimates, each LiDAR
# noise seed a lap), with each scan's situation class, into
# results/error_library.jld2 (not committed: regenerated by this script).
# The networks only watch: they run on each scan, but don't drive.
#
# Recorded along the racer's own path, not on LidarLaneNets.jl's training
# data (whose drives wander off the line on purpose, where some networks err
# more): calibrate.jl showed the difference (ψe's, sight's and the widths'
# errors twice as large there). On every track the networks never trained on
# (the validation and held-out tracks); a run on one of them never replays its
# own track's errors (runs.jl), so calibrate.jl can check the oracle there.
#
#     julia -t 4 --project=. error_library.jl

include(joinpath(@__DIR__, "runs.jl"))

const SETS = (car=:small_weak, cloud=:large)
const LIBRARY_TRACKS = vcat(VAL_TRACKS, TEST_TRACKS)
const LIBRARY_SEEDS = 1:3

function record(course, seed, ins, nets)
    labs, preds = LaneLabels[], Dict{Tuple{Symbol,Symbol},Tuple{Vector{Vector{Float64}},Vector{Vector{Float64}}}}()
    for role in keys(SETS), est in ESTIMATES
        preds[(est, role)] = (Vector{Float64}[], Vector{Float64}[])
    end
    function on_scan(ranges, labels)
        push!(labs, labels)
        for role in keys(SETS), est in ESTIMATES
            μ, σ = predict(nets[SETS[role]][est], ranges)
            push!(preds[(est, role)][1], μ .- labels[est])
            push!(preds[(est, role)][2], σ)
        end
    end
    run = simulate(reference(), course, ins; lidar_seed=seed, on_scan)
    return labs, preds, run.log.crashed
end

function main()
    ins = inputs(; nets=true, library=false)
    nets = ins[3]
    tasks = [(t, s) for t in LIBRARY_TRACKS for s in LIBRARY_SEEDS]
    results = Vector{Any}(undef, length(tasks))
    F1Tenth.THREAD_AGENTS[] = false
    Threads.@threads :dynamic for i in eachindex(tasks)
        t, s = tasks[i]
        results[i] = record(Course(t), s, ins, nets)
        @printf("%-14s seed %d: %d scans%s\n", t, s, length(results[i][1]), results[i][3] ? " (crashed)" : "")
        flush(stdout)
    end
    class = reduce(vcat, ([situation_class(l) for l in r[1]] for r in results))
    follows = reduce(vcat, ([trues(length(r[1]) - 1); false] for r in results))
    track = reduce(vcat, (fill(findfirst(==(tasks[i][1]), LIBRARY_TRACKS), length(results[i][1])) for i in eachindex(tasks)))
    features = reduce(hcat, (situation_features(l) for r in results for l in r[1]))
    truth = Dict(String(est) => Float32.(reduce(hcat, (l[est] for r in results for l in r[1]))) for est in ESTIMATES)
    err, sigma = Dict{Tuple{String,String},Matrix{Float32}}(), Dict{Tuple{String,String},Matrix{Float32}}()
    for role in keys(SETS), est in ESTIMATES
        err[(String(est), String(role))] = Float32.(reduce(hcat, reduce(vcat, (r[2][(est, role)][1] for r in results))))
        sigma[(String(est), String(role))] = Float32.(reduce(hcat, reduce(vcat, (r[2][(est, role)][2] for r in results))))
    end
    jldsave(joinpath(OUT, "error_library.jld2"); sets=[String(SETS.car), String(SETS.cloud)], tracks=LIBRARY_TRACKS,
        track, follows, features, truth, err, sigma)
    for (c, name) in enumerate(SITUATIONS)
        @printf("%-14s %6d scans\n", name, count(==(c), class))
    end
    # how large the errors are here, against the training data's (errors.md)
    for est in ESTIMATES, role in keys(SETS)
        e = abs.(err[(String(est), String(role))])
        @printf("%-10s %-6s median |error| %.4g, 90%% %.4g\n", est, role, median(e), quantile(vec(e), 0.9))
    end
end

if abspath(PROGRAM_FILE) == @__FILE__
    main()
end
